const step = $json.followup_step;
const name = $json.first_name || 'دوست عزیز';

const messages = {
  0: {
    text: `${name} جان، یه چیز جالب یادم افتاد که فکر می‌کنم برات مفید باشه...\n\nآیا می‌دونستی ۷۰٪ مشکلات زناشویی با یاد گرفتن چند تکنیک ساده قابل حله؟\n\nمی‌خوای بیشتر بدونی؟ 🌸`,
    next_step: 1
  },
  1: {
    text: `${name}، اجازه بده یه تجربه واقعی باهات به اشتراک بذارم:\n\n«من و همسرم ۵ سال بود داشتیم از هم دور می‌شدیم. فکر می‌کردیم همه زوج‌ها اینطورن. بعد از این دوره انگار دوباره عاشق شدیم.»\n— مریم، ۳۴ ساله\n\nمی‌خوای بدونی چطور؟`,
    next_step: 2
  },
  2: {
    text: `${name}، فقط می‌خواستم بدونی که این هفته یه فرصت خاص داریم:\n\n🎁 تخفیف ۲۰٪ برای ثبت‌نام تا پایان هفته\n📚 + کتاب صوتی «زبان عشق» رایگان\n\nاین پیشنهاد محدوده. می‌خوای جزئیات بیشتر بدونی؟`,
    next_step: 3
  },
  3: {
    text: `${name}، آخرین بار مزاحمت می‌شم 🙏\n\nمی‌دونم زندگی شلوغه. فقط بدون که هر وقت آماده شدی اینجام.\n\nبهترین سرمایه‌گذاری، سرمایه‌گذاری روی رابطه با عزیزترین آدم زندگیته 💙\n\nوقتی آماده شدی فقط بنویس: می‌خوام شروع کنم`,
    next_step: 4
  }
};

const msg = messages[step] || messages[0];
return [{ json: {
  telegram_id: $json.telegram_id,
  message: msg.text,
  next_step: msg.next_step
}}];
